import { createHash } from "node:crypto"

import type { SenderValues } from "@email-kit/core/internal"
import { DIALECT } from "@email-kit/dialect"

import { CLDR_VERSION } from "../../i18n/plurals.ts"
import { VERSION } from "../../version.ts"
import type { OutputFile } from "./index.ts"

/** The `$comment` of every generated JSON file. */
export const GENERATED =
  "Generated by email-kit. Do not edit: change the templates and run `email-kit compile`."

/** A template's entry in the manifest. */
export interface ManifestTemplate {
  readonly id: string
  readonly purpose: string
  /** The template's property on the generated `emails` object. */
  readonly property: string
  /** Its JSON Schema file. */
  readonly schema: string
  /** Each locale's subject, preheader, and the HTML and text files with their size and hash. */
  readonly locales: Readonly<Record<string, unknown>>
}

/**
 * manifest.json, written with `contract`: what was compiled, for tools that send the files
 * without the generated module. It records the versions that shaped the output (email-kit, the
 * template dialect, the CLDR plural data), the locales and sender values, each template's files,
 * and in `files` every file in the output folder.
 */
export function manifestFile(
  templates: readonly ManifestTemplate[],
  owned: readonly string[],
  options: { readonly locales: readonly string[]; readonly sender: SenderValues },
): OutputFile {
  return {
    path: "manifest.json",
    content: json({
      $comment: GENERATED,
      schemaVersion: 1,
      emailKit: VERSION,
      dialect: DIALECT,
      cldr: CLDR_VERSION,
      profiles: { subject: "text", preheader: "text", html: "html", text: "text" },
      locales: options.locales,
      sender: {
        constants: sortKeys(options.sender.constants),
        runtime: options.sender.runtime,
      },
      templates,
      files: [...owned, "manifest.json"].sort(),
    }),
  }
}

/** A file's path, size in bytes, and SHA-256, so a sender can check it has the right one. */
export function describe(file: OutputFile): { file: string; bytes: number; sha256: string } {
  const bytes = Buffer.byteLength(file.content, "utf8")
  const sha256 = createHash("sha256").update(file.content).digest("hex")
  return { file: file.path, bytes, sha256 }
}

/** JSON with two-space indents and a final newline. */
export function json(value: unknown): string {
  return `${JSON.stringify(value, null, 2)}\n`
}

/** The record without `undefined` values, its keys sorted so the output doesn't depend on order. */
function sortKeys(record: Readonly<Record<string, string | undefined>>): Record<string, string> {
  return Object.fromEntries(
    Object.entries(record)
      .filter((entry): entry is [string, string] => entry[1] !== undefined)
      .sort(([a], [b]) => (a < b ? -1 : 1)),
  )
}
